CREATE TABLE IF NOT EXISTS `dpn_medical_certifications` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`citizenid` varchar(64) NOT NULL,`certification` varchar(64) NOT NULL,`issued_by` varchar(64) NULL,`status` varchar(32) NOT NULL,`expires_at` datetime NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `uq_cert` (`citizenid`,`certification`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
